export async function createScene(engine, canvas, BABYLON) {
  console.clear();
  const scene = new BABYLON.Scene(engine);
  // scene.useRightHandedSystem = true;
  scene.clearColor = BABYLON.Color4.FromHexString("#01010BFF");

  var camera = new BABYLON.ArcRotateCamera("camera", BABYLON.Tools.ToRadians(90), BABYLON.Tools.ToRadians(65), 10, BABYLON.Vector3.Zero(), scene);
  camera.setTarget(new BABYLON.Vector3(0.07, 1.14, 0.06));
  camera.alpha = 1.571;
  camera.beta = 1.473;
  camera.radius = 4.8;
  camera.inertia = 0.4;
  camera.wheelDeltaPercentage = 0.3;
  camera.panningSensibility = 0;
  camera.minZ = 0.01;
  camera.maxZ = 100;
  camera.upperBetaLimit = Math.PI / 2;
  // camera.zoomToMouseLocation = true;
  camera.attachControl(canvas, true);

  var hemiLight = new BABYLON.HemisphericLight("light", new BABYLON.Vector3(0, 1, 0), scene);
  hemiLight.intensity = 0.1;

  var light = new BABYLON.DirectionalLight("dirLight", new BABYLON.Vector3(-1, -2, -1), scene);
  light.position = new BABYLON.Vector3(4, 8, 4);

  let rootMesh;
  let godrays, godraysMesh;
  let door;

  const sensitive = 0.01;
  let pickedMesh = null;
  let isRotating = false;
  let rotDirection = "y";
  let prePoint;

  BABYLON.SceneLoader.ImportMeshAsync("", "https://raw.githubusercontent.com/UN1TOne/3DAsset/master/", "fantasy door.glb").then((result) => {
    rootMesh = result.meshes[0];
    rootMesh.scaling.scaleInPlace(0.5);

    const environment = scene.createDefaultEnvironment({
      createGround: true,
      createSkybox: false,
      enableGroundMirror: true,
      groundMirrorSizeRatio: 0.15,
    });

    rootMesh.getChildMeshes().forEach((m) => {
      if (m.name === "door") {
        door = m;

        godraysMesh = door.clone("godraysMesh");
      }

      if (m.material) {
        m.material.needDepthPrePass = true;
        m.material.backFaceCulling = false;
      }
    });

    // door interaction with mouse drag
    const startRotationQuaternion = door.rotationQuaternion.clone();

    const maxRotationAngle = BABYLON.Tools.ToRadians(120);
    const minRotationAngle = BABYLON.Tools.ToRadians(-120);

    scene.onPointerObservable.add((evt) => {
      const x = evt.event.offsetX;
      const y = evt.event.offsetY;

      const camera = scene.activeCamera;

      if (evt.type === BABYLON.PointerEventTypes.POINTERDOWN) {
        const pickInfo = scene.pick(x, y);
        if (pickInfo?.hit) {
          pickedMesh = pickInfo.pickedMesh;
          prePoint = { x, y };
          isRotating = true;

          if (pickedMesh === door) {
            camera.detachControl();

            light.intensity = 3;
          }
        }
      }

      if (evt.type === BABYLON.PointerEventTypes.POINTERMOVE && isRotating) {
        if (prePoint) {
          const amountX = (x - prePoint.x) * sensitive;

          if (rotDirection === "y" && pickedMesh === door) {
            const currentEuler = door.rotationQuaternion.toEulerAngles();
            let newRotation = BABYLON.Scalar.Clamp(currentEuler.y + amountX, minRotationAngle, maxRotationAngle);

            door.rotationQuaternion = BABYLON.Quaternion.RotationAxis(BABYLON.Axis.Y, newRotation);
          }

          prePoint = { x, y };
        }
      }

      if (evt.type === BABYLON.PointerEventTypes.POINTERUP) {
        camera.attachControl();
        isRotating = false;

        if (pickedMesh === door) {
          const animation = new BABYLON.Animation(
            "resetRotationQuaternion",
            "rotationQuaternion",
            60,
            BABYLON.Animation.ANIMATIONTYPE_QUATERNION,
            BABYLON.Animation.ANIMATIONLOOPMODE_CONSTANT
          );

          const keys = [
            { frame: 0, value: door.rotationQuaternion.clone() },
            { frame: 30, value: startRotationQuaternion.clone() },
          ];
          animation.setKeys(keys);

          door.animations = [animation];
          scene.beginAnimation(door, 0, 30, false, 1, () => {
            if (godraysMesh) godraysMesh.material.diffuseColor = getRandomSoftColor();
            light.intensity = 1;
          });
        }

        pickedMesh = null;
      }
    });

    // godray
    createGodrays();

    const pipeline = new BABYLON.DefaultRenderingPipeline("pipeline", true, scene, [camera]);
    pipeline.bloomEnabled = true;
    pipeline.bloomThreshold = 0.8;
    pipeline.bloomIntensity = 0.5;

    pipeline.fxaaEnabled = true;

    pipeline.glowLayerEnabled = true;
    pipeline.glowLayer.intensity = 5;

    pipeline.imageProcessing.vignetteEnabled = true;
    pipeline.imageProcessing.vignetteWeight = 4;
    pipeline.imageProcessing.vignetteCameraFov = 1.1;

    pipeline.sharpenEnabled = true;

    scene.imageProcessingConfiguration.toneMappingEnabled = true;
    scene.imageProcessingConfiguration.toneMappingType = BABYLON.ImageProcessingConfiguration.TONEMAPPING_ACES;
  });

  function createGodrays() {
    godraysMesh.material = new BABYLON.StandardMaterial("godraysMaterial", scene);
    godraysMesh.material.diffuseColor = getRandomSoftColor();
    // godraysMesh.isVisible = false;

    godrays = new BABYLON.VolumetricLightScatteringPostProcess(
      "godrays",
      1.0,
      camera,
      godraysMesh,
      100,
      BABYLON.Texture.BILINEAR_SAMPLINGMODE,
      engine,
      false
    );
    godrays.mesh.position.z = -0.113;

    scene.onBeforeRenderObservable.add(() => {
      const cameraDirection = camera.getForwardRay().direction;
      const forwardPlaneNormal = new BABYLON.Vector3(0, 0, 1);
      const dotProduct = BABYLON.Vector3.Dot(cameraDirection, forwardPlaneNormal);

      if (dotProduct < -0.15) {
        godrays.mesh.isVisible = true;
      } else {
        godrays.mesh.isVisible = false;
      }
    });
  }

  function getRandomSoftColor() {
    const r = Math.random() * 0.5 + 0.5; // 0.5 ~ 1.0
    const g = Math.random() * 0.5 + 0.5; // 0.5 ~ 1.0
    const b = Math.random() * 0.5 + 0.5; // 0.5 ~ 1.0

    return new BABYLON.Color3(r, g, b);
  }

  return scene;
}
